def count_substring_occurrences(text: str, substring: str) -> int:
    """
    Counts how many times a substring appears in a string by checking every possible starting position.
    Uses overlapping occurrences (e.g., 'aa' in 'aaa' is counted twice).
    """
    if not substring:
        return 0

    len_text = len(text)
    len_sub = len(substring)

    if len_sub > len_text:
        return 0

    # Check every possible starting position in the text
    return sum(1 for i in range(len_text - len_sub + 1) 
               if text[i:i + len_sub] == substring)

