def returns_larger_number_ignores_commas(*args):
    """
    Accepts variable arguments (strings or numbers).
    Removes all commas from string arguments, converts to float,
    and returns the largest number.
    """
    if not args:
        return None

    def parse_value(val):
        if isinstance(val, str):
            # Remove commas and strip whitespace
            cleaned = val.replace(',', '').strip()
            return float(cleaned)
        return float(val)

    try:
        numbers = [parse_value(arg) for arg in args]
        return max(numbers)
    except (ValueError, TypeError) as e:
        raise ValueError(f"Could not convert input to number: {e}")

