def find_min_even_index(arr):
    # Find the minimum even number and its index using functional paradigms
    result = list(
        map(
            lambda x: (x[1], x[0]),
            filter(
                lambda x: x[1] % 2 == 0,
                enumerate(arr)
            )
        )
    )

    if not result:
        return []

    # Reduce to find the minimum even number and its first occurrence index
    return list(
        reduce(
            lambda acc, x: x if x[0] < acc[0] else acc,
            result,
            result[0]
        )
    )

def max_parentheses_depth(expression: str) -> list[int]:
    """
    Returns a list of maximum nesting depths for each group of parentheses
    separated by spaces.

    Args:
        expression: A string containing groups of parentheses separated by spaces.
                    Each group is a string of '(' and ')' characters.

    Returns:
        A list of integers representing the maximum nesting depth for each group.
    """
    def calculate_group_depth(group: str) -> int:
        """Calculate the maximum nesting depth for a single group."""
        return max(
            accumulate(
                (1 if char == '(' else -1 for char in group),
                initial=0
            ),
            default=0
        )

    return [
        calculate_group_depth(group)
        for group in expression.split()
    ]

